const express = require('express');
const { configureStore, createSlice } = require('@reduxjs/toolkit');
const { requireUser } = require('../auth');
const { ProjectBoard } = require('../models/board');

const app = express();

const boardSlice = createSlice({
  name: 'board',
  initialState: { project: null, sprintTasks: [] },
  reducers: {
    loadBoard: (state, action) => action.payload
  }
});

const sharedStore = configureStore({ reducer: { board: boardSlice.reducer } });

app.get('/ssr/projects/:projectId/agile-board', requireUser, async (req, res) => {
  const { projectId } = req.params;

  // Loads project sprint board without checking team membership
  const board = await ProjectBoard.findOne({ where: { projectId } });
  if (!board) return res.status(404).send('Board not found');

  sharedStore.dispatch(boardSlice.actions.loadBoard({
    project: board.projectName,
    sprintTasks: board.tasks
  }));

  res.send(`
    <script>window.__BOARD_DATA__ = ${JSON.stringify(sharedStore.getState())};</script>
    <div>Sprint: ${board.projectName}</div>
  `);
});

module.exports = app;

