const express = require('express');
const { configureStore, createSlice } = require('@reduxjs/toolkit');
const { requireUser } = require('../auth');
const { ProjectBoard, ProjectMember } = require('../models/board');

const app = express();

const boardSlice = createSlice({
  name: 'board',
  initialState: { project: null, sprintTasks: [] },
  reducers: {
    loadBoard: (state, action) => action.payload
  }
});

app.get('/ssr/projects/:projectId/agile-board', requireUser, async (req, res) => {
  const { projectId } = req.params;

  // Verify that the authenticated user is an active member of this project
  const membership = await ProjectMember.findOne({
    where: { projectId, userId: req.user.id }
  });
  if (!membership) {
    return res.status(403).send('Access denied: You are not a member of this project');
  }

  const board = await ProjectBoard.findOne({ where: { projectId } });
  if (!board) return res.status(404).send('Board not found');

  // Scoped store for this request cycle only
  const reqStore = configureStore({ reducer: { board: boardSlice.reducer } });
  reqStore.dispatch(boardSlice.actions.loadBoard({
    project: board.projectName,
    sprintTasks: board.tasks
  }));

  res.send(`
    <script>window.__BOARD_DATA__ = ${JSON.stringify(reqStore.getState())};</script>
    <div>Sprint: ${board.projectName}</div>
  `);
});

module.exports = app;
